  $('gallery-scope-toggle').addEventListener('click',()=>{const current=photos[photoIndex];if(!current)return;galleryScope=galleryScope==='place'?'city':'place';photos=galleryScope==='city'?allPhotos:allPhotos.filter(p=>p.id===current.id);photoIndex=Math.max(0,photos.findIndex(p=>p.image===current.image));renderGallery();});
  $('gallery-close').addEventListener('click',()=>$('gallery-dialog').close());if($('people-close'))$('people-close').addEventListener('click',()=>$('people-dialog').close());$('gallery-prev').addEventListener('click',()=>movePhoto(-1));$('gallery-next').addEventListener('click',()=>movePhoto(1));$('gallery-image').addEventListener('error',()=>{$('gallery-error').hidden=false;$('gallery-image').hidden=true;});
  $('gallery-dialog').addEventListener('close',()=>{document.body.classList.remove('gallery-open');galleryReturn?.focus?.({preventScroll:true});});
  $('gallery-dialog').addEventListener('keydown',event=>{if(event.key==='ArrowRight'){event.preventDefault();movePhoto(1);}if(event.key==='ArrowLeft'){event.preventDefault();movePhoto(-1);}});
  let touchX=null;$('gallery-stage').addEventListener('touchstart',event=>{if(event.touches.length===1)touchX=event.touches[0].clientX;},{passive:true});$('gallery-stage').addEventListener('touchend',event=>{if(touchX!==null&&event.changedTouches.length){const delta=event.changedTouches[0].clientX-touchX;if(Math.abs(delta)>55)movePhoto(delta<0?1:-1);}touchX=null;},{passive:true});
  window.addEventListener('storage',event=>{if(event.key===KEYS.favorites)favorites=read(KEYS.favorites);else if(event.key===KEYS.plan)plan=read(KEYS.plan);else return;updateCounts();syncButtons();if(view!=='base')renderPanel();if($('gallery-dialog').open)renderGallery();});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){decorateCards();void loadCurrentUser();}});
  void loadCurrentUser();
